package practice;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Maps the "type" field of an incoming webhook payload to the record class the payload is
 * decoded into: "delivered" to Delivered, for example.
 */
public final class PayloadTypes {

    private PayloadTypes() {
    }

    /**
     * Every record class a value of {@code root} can be, keyed by its simple name in lower case.
     * The decoder builds this once at startup and rejects any payload whose type isn't a key.
     */
    public static Map<String, Class<?>> of(Class<?> root) {
        Map<String, Class<?>> types = new HashMap<>();
        collect(root, types);
        return Map.copyOf(types);
    }

    /** Registers one payload record under its key. */
    static void register(Class<?> record, Map<String, Class<?>> types) {
        types.put(record.getSimpleName().toLowerCase(Locale.ROOT), record);
    }

    /**
     * Adds to {@code types} every record class a value of {@code type} can be. The map must be
     * complete: when that can't be known from {@code type}, throw IllegalArgumentException.
     */
    static void collect(Class<?> type, Map<String, Class<?>> types) {
        if (type.isRecord()) {
            register(type, types);
            return;
        }
        Class<?>[] permitted = type.getPermittedSubclasses();
        if (permitted == null) {
            throw new IllegalArgumentException(type.getName() + " is not sealed");
        }
        for (Class<?> subtype : permitted) {
            collect(subtype, types);
        }
    }
}

package practice;

import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            System.out.println("order events: " + new java.util.TreeMap<>(PayloadTypes.of(OrderEvent.class)).keySet());
            System.out.println("billing events: " + new java.util.TreeMap<>(PayloadTypes.of(BillingEvent.class)).keySet());
            System.out.println("\"declined\" decodes into: " + PayloadTypes.of(BillingEvent.class).get("declined").getSimpleName());
            try {
                PayloadTypes.of(Reminder.class);
                System.out.println("reminders: mapped");
            } catch (IllegalArgumentException refused) {
                System.out.println("reminders: refused, " + refused.getMessage());
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    sealed interface OrderEvent permits Placed, Shipped {}

    record Placed(String order) implements OrderEvent {}

    record Shipped(String order, String carrier) implements OrderEvent {}

    sealed interface BillingEvent permits Paid, Failure {}

    record Paid(String invoice) implements BillingEvent {}

    sealed interface Failure extends BillingEvent permits Declined, TimedOut {}

    record Declined(String invoice, String code) implements Failure {}

    record TimedOut(String invoice) implements Failure {}

    interface Reminder {}
}

